      fish: { name: __alloT('stem.coralreef.inv_m_part_belt', 'Fish and invertebrates'), hint: __alloT('stem.coralreef.w2_m_part_fish_hint', 'A belt beside the tape') },
      guide: { name: __alloT('stem.coralreef.w2_m_part_guide', 'Field guide'), hint: __alloT('stem.coralreef.w2_m_part_guide_hint', 'What can be under a point') },
