    '[data-coralreef-root] .cr-scilab-tab small{font-size:12px;font-weight:500}',
    '[data-coralreef-root] .cr-scilab-tab:focus-visible,[data-coralreef-root] .cr-scilab-inv button:focus-visible{outline:3px solid var(--reef-accent);outline-offset:2px}',
